import ast

def extract_variable_names(filename):
    with open(filename, 'r') as file:
        tree = ast.parse(file.read())

    variable_names = set()

    for node in ast.walk(tree):
        if isinstance(node, ast.Name):
            variable_names.add(node.id)

    return variable_names

